'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let pos = 0;

const n = input[pos++];
const m = input[pos++];

const st = new Int32Array(n);
const mark = new Uint8Array(n);
const ans = new Uint8Array(n);
const adj = Array.from({ length: n }, () => []);
const adjr = Array.from({ length: n }, () => []);

for (let i = 0; i < n; i++) {
    st[i] = input[pos++];
}

for (let i = 0; i < m; i++) {
    const u = input[pos++] - 1;
    const v = input[pos++] - 1;
    adj[u].push(v);
    adjr[v].push(u);
}

function dfs1(start) {
    const stack = [start];
    mark[start] = 1;

    while (stack.length > 0) {
        const x = stack.pop();
        ans[x]++;

        for (const u of adj[x]) {
            if (!mark[u]) {
                mark[u] = 1;
                stack.push(u);
            }
        }
    }
}

function dfs2(start) {
    const stack = [start];
    mark[start] = 1;

    while (stack.length > 0) {
        const x = stack.pop();
        ans[x]++;

        if (st[x] === 1) continue;

        for (const u of adjr[x]) {
            if (!mark[u]) {
                mark[u] = 1;
                stack.push(u);
            }
        }
    }
}

for (let i = 0; i < n; i++) {
    if (!mark[i] && st[i] === 1) {
        dfs1(i);
    }
}

mark.fill(0);

for (let i = 0; i < n; i++) {
    if (!mark[i] && st[i] === 2) {
        dfs2(i);
    }
}

const output = new Array(n);
for (let i = 0; i < n; i++) {
    output[i] = ans[i] === 2 ? '1' : '0';
}

console.log(output.join('\n'));

